#[test]
fn avx512_unimplemented_evex_case_variants_have_generated_byte_coverage() {
    let llvm_mc = llvm_mc_path();
    if llvm_mc.is_none() {
        eprintln!("[info] llvm-mc unavailable; using raw EVEX spec bytes");
    }

    let rows = avx512_spec_evex_rows();
    let known_unimplemented = set_from_manifest(UNIMPLEMENTED_AVX512);
    let expected_case_variants = rows
        .iter()
        .filter(|row| known_unimplemented.contains(&row.key.mnemonic))
        .flat_map(|row| {
            evex_case_variants_for_row(row)
                .into_iter()
                .map(|variant| spec_case_variant_id(row, variant))
        })
        .collect::<BTreeSet<_>>();
    let cases = generated_unimplemented_cases(&rows);

    if expected_case_variants.is_empty() {
        assert!(
            cases.is_empty(),
            "unimplemented AVX-512 EVEX byte corpus must be empty when the manifest is empty"
        );
        return;
    }
    assert!(
        cases.len() >= expected_case_variants.len(),
        "unimplemented EVEX byte coverage must include split register/memory and r/m-extension forms"
    );

    for row in rows
        .iter()
        .filter(|row| known_unimplemented.contains(&row.key.mnemonic))
    {
        if !evex_asm_modes_for_row(row).contains(&EvexAsmMode::Register) {
            continue;
        }

        let actual_rm_regs = cases
            .iter()
            .filter(|case| {
                case.source == row.source
                    && case.cell == row.cell
                    && case.variant.mode == EvexAsmMode::Register
            })
            .filter_map(|case| case.variant.rm_reg)
            .collect::<BTreeSet<_>>();
        let expected_rm_regs = evex_rm_register_buckets_for_row(row)
            .into_iter()
            .collect::<BTreeSet<_>>();
        assert_eq!(
            actual_rm_regs,
            expected_rm_regs,
            "{} must cover every valid EVEX r/m register bucket for its operand class",
            spec_row_mode_id(row, EvexAsmMode::Register)
        );

        if avx512_spec::evex_rm_register_class(row) == EvexRmRegisterClass::Vector {
            assert_eq!(
                actual_rm_regs,
                BTreeSet::from([0, 8, 16, 24]),
                "{} must cover all vector EVEX.X/B r/m extension buckets",
                spec_row_mode_id(row, EvexAsmMode::Register)
            );
        }
    }

    let mut failures = Vec::new();
    let mut covered_case_variants = BTreeSet::new();

    for case in &cases {
        let llvm_bytes = llvm_mc
            .as_deref()
            .and_then(|llvm_mc| assemble_intel_case(llvm_mc, &case.asm));
        let bytes = match llvm_bytes {
            Some(bytes) if assert_bytes_match_spec_case(case, &bytes).is_ok() => bytes,
            _ => case.op.clone(),
        };

        if let Err(error) = assert_bytes_match_spec_case(case, &bytes) {
            failures.push(format!(
                "{}: {error}\n  spec: {}\n  asm: {}\n  bytes: {:02x?}",
                generated_case_id(case),
                case.cell,
                case.asm,
                bytes
            ));
            continue;
        }

        covered_case_variants.insert(generated_case_id(case));
    }

    let missing_case_variants = expected_case_variants
        .difference(&covered_case_variants)
        .cloned()
        .collect::<BTreeSet<_>>();

    assert!(
        failures.is_empty() && missing_case_variants.is_empty(),
        "unimplemented AVX-512 EVEX byte coverage mismatch\nfailures:\n{}\nmissing case variants:\n{}",
        failures.into_iter().take(80).collect::<Vec<_>>().join("\n"),
        format_row_set(&missing_case_variants)
    );
}

/// Diagnostic used while closing the independent x86-to-SMIR coverage gap.
/// It intentionally remains ignored until the residual set is empty; unlike
/// the legacy executor mnemonic inventory, this exercises each generated EVEX
/// row and r/m-extension variant through the production SMIR lifter.
#[test]
#[ignore = "diagnostic: reports residual EVEX forms rejected by the SMIR lifter"]
fn report_evex_spec_forms_rejected_by_smir_lifter() {
    let mut rejected = BTreeMap::<String, (usize, String)>::new();
    let mut accepted = 0usize;
    for row in avx512_spec_evex_rows() {
        for variant in evex_case_variants_for_row(&row) {
            let bytes = raw_evex_spec_bytes_for_variant(&row, variant);
            let mut lifter = X86_64Lifter::new();
            let mut ctx = LiftContext::new(SourceArch::X86_64);
            match lifter.lift_insn(0x1000, &bytes, &mut ctx) {
                Ok(result) if result.bytes_consumed == bytes.len() => accepted += 1,
                Ok(result) => {
                    let detail = format!(
                        "{}: consumed {}/{} bytes ({:02X?})",
                        spec_case_variant_id(&row, variant),
                        result.bytes_consumed,
                        bytes.len(),
                        bytes
                    );
                    let entry = rejected
                        .entry(row.key.mnemonic.clone())
                        .or_insert((0, detail));
                    entry.0 += 1;
                }
                Err(error) => {
                    let detail = format!(
                        "{}: {error:?} ({:02X?})",
                        spec_case_variant_id(&row, variant),
                        bytes
                    );
                    let entry = rejected
                        .entry(row.key.mnemonic.clone())
                        .or_insert((0, detail));
                    entry.0 += 1;
                }
            }
        }
    }
    assert!(
        rejected.is_empty(),
        "accepted {accepted} EVEX forms; rejected {} mnemonics / {} forms:\n{}",
        rejected.len(),
        rejected.values().map(|entry| entry.0).sum::<usize>(),
        rejected
            .iter()
            .map(|(mnemonic, (count, detail))| format!("{mnemonic}: {count} ({detail})"))
            .collect::<Vec<_>>()
            .join("\n")
    );
    eprintln!("EVEX specification forms: lifted {accepted}, rejected 0");
}

/// Diagnostic for the second half of the native-admission boundary. Every
/// generated EVEX form accepted by the production lifter is optimized at O2
/// and presented to a production-configured x86-64 lowerer as a
/// one-instruction function. When `smir-jit` is enabled, the form must first
/// pass the production clobber/admission gate with memory helpers enabled. This
/// distinguishes absent instruction families from latent runtime-gate and
/// configured-lowerer coverage gaps while keeping the lowerer diagnostic
/// buildable in the non-JIT x86-64 suite.
#[test]
#[ignore = "diagnostic: reports EVEX forms accepted by the lifter but rejected by the lowerer"]
fn report_evex_spec_forms_accepted_by_lifter_but_rejected_by_lowerer() {
    let mut register_gate_failures = BTreeMap::<String, (usize, String)>::new();
    let mut memory_gate_failures = BTreeMap::<String, (usize, String)>::new();
    let mut lower_failures = BTreeMap::<String, (usize, String)>::new();
    let mut lifted = 0usize;
    let mut admitted = 0usize;
    let mut lowered = 0usize;

    for row in avx512_spec_evex_rows() {
        for variant in evex_case_variants_for_row(&row) {
            let bytes = raw_evex_spec_bytes_for_variant(&row, variant);
            let mut lifter = X86_64Lifter::new();
            let mut ctx = LiftContext::new(SourceArch::X86_64);
            let result = match lifter.lift_insn(0x1000, &bytes, &mut ctx) {
                Ok(result) if result.bytes_consumed == bytes.len() => result,
                _ => continue,
            };
            lifted += 1;

            let mut block = SmirBlock::new(BlockId(0), 0x1000);
            for op in result.ops {
                block.push_op(op);
            }
            block.set_terminator(Terminator::Return { values: vec![] });
            let mut function = SmirFunction::new(FunctionId(0), BlockId(0), 0x1000);
            function.add_block(block);
            function.x86_instruction_bytes.insert(
                (BlockId(0), 0x1000),
                X86InstructionBytes::new(&bytes).expect("generated x86 instruction length"),
            );
            optimize_function(&mut function, OptLevel::O2);

            #[cfg(feature = "smir-jit")]
            {
                if !is_native_clobber_safe_excluding(
                    &function,
                    &std::collections::HashMap::new(),
                    true,
                ) {
                    let detail = format!(
                        "{}: runtime gate rejected ({bytes:02X?})",
                        spec_case_variant_id(&row, variant)
                    );
                    let failures = match variant.mode {
                        EvexAsmMode::Register => &mut register_gate_failures,
                        EvexAsmMode::Memory => &mut memory_gate_failures,
                    };
                    let entry = failures
                        .entry(row.key.mnemonic.clone())
                        .or_insert((0, detail));
                    entry.0 += 1;
                    continue;
                }
                admitted += 1;
            }

            let mut lowerer = X86_64Lowerer::new();
            lowerer.set_mem_helpers(true);
            lowerer.set_preserve_vector_mem_helpers(true);
            lowerer.set_guest_pcrel_lea_immediates(true);
            lowerer.set_jit_fault_deopt_guards(true);
            #[cfg(feature = "smir-jit")]
            {
                // Mirror the production bridge decision, not only memory
                // helper preservation. VSIB commits state even on empty masks.
                let excluded = std::collections::HashMap::new();
                let uses_vector = uses_x86_native_vectors_excluding(&function, &excluded);
                lowerer.set_native_vector_state_active(uses_vector);
                lowerer.set_narrow_vector_opmask_helpers(
                    uses_vector
                        && x86_native_vector_uses_k16_opmasks_excluding(&function, &excluded),
                );
            }
            match lowerer.lower_function(&function) {
                Ok(_) => lowered += 1,
                Err(error) => {
                    let detail = format!(
                        "{}: {error:?} ({bytes:02X?})",
                        spec_case_variant_id(&row, variant)
                    );
                    let entry = lower_failures
                        .entry(row.key.mnemonic.clone())
                        .or_insert((0, detail));
                    entry.0 += 1;
                }
            }
        }
    }

    eprintln!(
        "EVEX specification forms: lifted {lifted}, admitted {admitted}, lowered {lowered}; runtime gate enabled: {}",
        cfg!(feature = "smir-jit")
    );
    assert!(
        register_gate_failures.is_empty()
            && memory_gate_failures.is_empty()
            && lower_failures.is_empty(),
        "lifted {lifted} EVEX forms; runtime gate enabled: {}; admitted {admitted}; lowered {lowered}\nregister gate gaps: {} mnemonics / {} forms:\n{}\nmemory gate gaps: {} mnemonics / {} forms:\n{}\nconfigured-lowerer gaps: {} mnemonics / {} forms:\n{}",
        cfg!(feature = "smir-jit"),
        register_gate_failures.len(),
        register_gate_failures
            .values()
            .map(|entry| entry.0)
            .sum::<usize>(),
        register_gate_failures
            .iter()
            .map(|(mnemonic, (count, detail))| format!("{mnemonic}: {count} ({detail})"))
            .collect::<Vec<_>>()
            .join("\n"),
        memory_gate_failures.len(),
        memory_gate_failures
            .values()
            .map(|entry| entry.0)
            .sum::<usize>(),
        format_row_set(
            &memory_gate_failures
                .iter()
                .map(|(mnemonic, (count, detail))| format!("{mnemonic}: {count} ({detail})"))
                .collect()
        ),
        lower_failures.len(),
        lower_failures.values().map(|entry| entry.0).sum::<usize>(),
        lower_failures
            .iter()
            .map(|(mnemonic, (count, detail))| format!("{mnemonic}: {count} ({detail})"))
            .collect::<Vec<_>>()
            .join("\n")
    );
}

#[test]
fn evex_sparse_prefetch_hints_close_generated_lift_lower_gap() {
    let expected_mnemonics = set_from_slice(&[
        "vgatherpf0dpd",
        "vgatherpf0dps",
        "vgatherpf0qpd",
        "vgatherpf0qps",
        "vgatherpf1dpd",
        "vgatherpf1dps",
        "vgatherpf1qpd",
        "vgatherpf1qps",
        "vscatterpf0dpd",
        "vscatterpf0dps",
        "vscatterpf0qpd",
        "vscatterpf0qps",
        "vscatterpf1dpd",
        "vscatterpf1dps",
        "vscatterpf1qpd",
        "vscatterpf1qps",
    ]);
    let mut covered_mnemonics = BTreeSet::new();
    let mut covered_forms = 0usize;

    for row in avx512_spec_evex_rows() {
        if !expected_mnemonics.contains(&row.key.mnemonic) {
            continue;
        }
        for variant in evex_case_variants_for_row(&row) {
            assert_eq!(variant.mode, EvexAsmMode::Memory);
            let bytes = raw_evex_spec_bytes_for_variant(&row, variant);
            let instruction = X86InstructionBytes::new(&bytes).unwrap();
            let mut lifter = X86_64Lifter::new();
            let mut ctx = LiftContext::new(SourceArch::X86_64);
            let result = lifter
                .lift_insn(0x1000, &bytes, &mut ctx)
                .unwrap_or_else(|error| {
                    panic!(
                        "{}: sparse-prefetch hint failed to lift: {error:?}",
                        spec_case_variant_id(&row, variant)
                    )
                });
            assert_eq!(result.bytes_consumed, bytes.len());
            assert!(result.ops.is_empty());

            let mut block = SmirBlock::new(BlockId(0), 0x1000);
            block.ops = result.ops;
            block.set_terminator(Terminator::Return { values: vec![] });
            let mut function = SmirFunction::new(FunctionId(0), BlockId(0), 0x1000);
            function.add_block(block);
            function
                .x86_instruction_bytes
                .insert((BlockId(0), 0x1000), instruction);
            let mut lowerer = X86_64Lowerer::new();
            lowerer.lower_function(&function).unwrap_or_else(|error| {
                panic!(
                    "{}: sparse-prefetch hint failed to lower: {error:?}",
                    spec_case_variant_id(&row, variant)
                )
            });

            covered_mnemonics.insert(row.key.mnemonic.clone());
            covered_forms += 1;
        }
    }

    assert_eq!(covered_mnemonics, expected_mnemonics);
    assert_eq!(covered_forms, 32);
}

